<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class AttestationDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-clipboard-check';protected static ?string $navigationLabel='Ведомости и пересдачи';protected static ?string $navigationGroup='Учебная часть';protected static string $view='filament.pages.attestation-dashboard';public array $sheets=[],$stats=[];
public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$q=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->leftJoin('teachers as t','t.id','=','a.teacher_id')->where('a.academic_period_id',$p->id)->select('a.*','g.name as group_name','s.name as subject_name','t.last_name as teacher_last_name')->orderByDesc('a.id');$this->sheets=$q->get()->map(function($x){$latest=DB::table('attestation_attempts')->where('attestation_sheet_id',$x->id)->orderBy('student_id')->orderByDesc('attempt_no')->get()->unique('student_id');$x->debts=$latest->where('passed',0)->whereNotNull('completed_at')->count();$x->unfilled=DB::table('attestation_attempts')->where(['attestation_sheet_id'=>$x->id,'attempt_no'=>0])->whereNull('completed_at')->count();return(array)$x;})->all();$this->stats=['open'=>collect($this->sheets)->where('status','open')->count(),'closed'=>collect($this->sheets)->where('status','closed')->count(),'debts'=>collect($this->sheets)->sum('debts'),'unfilled'=>collect($this->sheets)->sum('unfilled')];}
public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('semester.mark'));}}